WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD  = #{siteCd}
  AND A.USER_CD  = #{userCd}
  AND A.DEL_YN   = 'N'
  AND A.REQ_TYPE IN ('01','02','03','04','05','06','10')

  AND A.REQ_TYPE IN

    #{t}



  AND A.REQ_STATUS IN

    #{s}



  AND A.WORK_YMD >= #{targetYmdFrom}


  AND A.WORK_YMD <= #{targetYmdTo}

mapper.select:
/* AppReq06Mapper.selectMyTotalCount */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.DEL_YN   = 'N'
   AND A.REQ_TYPE IN ('01','02','03','04','05','06','10')

/* AppReq06Mapper.selectMyFilteredCount */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ A

/* AppReq06Mapper.selectMyReqPage */ SELECT A.REQ_ID AS reqId , A.REQ_TYPE AS reqType , A.REQ_STATUS AS reqStatus , A.WORK_YMD AS workYmd , A.START_DATE AS startDate , A.START_TIME AS startTime , A.END_DATE AS endDate , A.END_TIME AS endTime , A.LEAVE_TYPE AS leaveType , A.LEAVE_DAYS AS leaveDays , A.SCH_CD AS schCd , A.PROCESS_COMMENT AS processComment , A.PROCESS_DATE AS processDate , A.INSERT_DATE AS insertDate FROM TB_USER_ATTD_REQ A
ORDER BY A.INSERT_DATE DESC, A.REQ_ID DESC
ORDER BY ABS(DATEDIFF(STR_TO_DATE(COALESCE(A.WORK_YMD,'99991231'),'%Y%m%d'), CURDATE())) ASC , A.INSERT_DATE DESC , A.REQ_ID DESC
ORDER BY (CASE A.REQ_STATUS WHEN '01' THEN 0 ELSE 1 END) ASC , A.INSERT_DATE DESC , A.REQ_ID DESC
LIMIT #{limit} OFFSET #{offset}
